import os
from dataclasses import dataclass
from typing import Optional

import requests
from openai import OpenAI


OPENAI_TRANSCRIPTION_BASE_URL = "https://api.openai.com/v1"
OPENAI_TRANSCRIPTION_MODEL = "gpt-4o-transcribe"


@dataclass(frozen=True)
class SpeechClientConfig:
    api_key: str
    model: str = OPENAI_TRANSCRIPTION_MODEL
    base_url: str = OPENAI_TRANSCRIPTION_BASE_URL
    timeout: int = 120


def get_speech_client_config(api_key: Optional[str] = None, model: str = OPENAI_TRANSCRIPTION_MODEL, timeout: int = 120) -> SpeechClientConfig:
    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise ValueError("OPENAI_API_KEY is required")
    return SpeechClientConfig(api_key=key, model=model, timeout=timeout)


def create_openai_client(api_key: Optional[str] = None) -> OpenAI:
    config = get_speech_client_config(api_key=api_key)
    return OpenAI(api_key=config.api_key)


def create_http_session(api_key: Optional[str] = None) -> requests.Session:
    config = get_speech_client_config(api_key=api_key)
    session = requests.Session()
    session.headers.update({"Authorization": f"Bearer {config.api_key}"})
    return session

import os
from typing import Any, Dict, List, Optional

from openai import OpenAI


def _normalize_items(items: Optional[List[Dict[str, Any]]]) -> List[Dict[str, Any]]:
    normalized: List[Dict[str, Any]] = []
    if not items:
        return normalized
    for item in items:
        start = item.get("start")
        end = item.get("end")
        text = item.get("text") or item.get("word") or item.get("segment")
        entry: Dict[str, Any] = {"text": text}
        if start is not None:
            entry["start"] = start
        if end is not None:
            entry["end"] = end
        if "speaker" in item:
            entry["speaker"] = item["speaker"]
        normalized.append(entry)
    return normalized


def timestamped_transcript(transcription: Dict[str, Any], granularity: str = "segment") -> Dict[str, Any]:
    if granularity not in {"word", "segment"}:
        raise ValueError("granularity must be 'word' or 'segment'")
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))
    _ = client
    timestamps_key = "words" if granularity == "word" else "segments"
    return {
        "transcript": transcription.get("text") or transcription.get("transcript") or "",
        "timestamps": _normalize_items(transcription.get(timestamps_key)),
        "provider": "openai",
        "model": transcription.get("model") or "gpt-4o-transcribe",
    }

